def hollow_hourglass(n):
    total_rows = 2 * n - 1
    for r in range(1, total_rows + 1):          # r counts every row, top edge to bottom edge
        m = min(r, 2 * n - r)                     # this row's distance from the nearest edge
        gap = m - 1
        stars = 2 * (n - m) + 1
        for j in range(gap + stars):               # check every column this row actually uses
            if j < gap:
                print(" ", end="")                    # still inside the leading gap
                continue
            k = j - gap                             # position inside the star region
            if m == 1:
                print("*", end="")                    # the top or bottom rim is completely solid
            elif k == 0 or k == stars - 1:
                print("*", end="")                    # left or right edge of this row
            else:
                print(" ", end="")                    # interior of this row stays hollow
        print()                                    # move to the next line after the row


if __name__ == "__main__":
    hollow_hourglass(4)

