public class Main {
    void hollowHourglass(int n) {
        int totalRows = 2 * n - 1;
        for (int r = 1; r <= totalRows; r++) {         // r counts every row, top edge to bottom edge
            int m = Math.min(r, 2 * n - r);              // this row's distance from the nearest edge
            int gap = m - 1;
            int stars = 2 * (n - m) + 1;
            for (int j = 0; j < gap + stars; j++) {       // check every column this row actually uses
                if (j < gap) {
                    System.out.print(" ");                    // still inside the leading gap
                    continue;
                }
                int k = j - gap;                            // position inside the star region
                if (m == 1) {
                    System.out.print("*");                    // the top or bottom rim is completely solid
                } else if (k == 0 || k == stars - 1) {
                    System.out.print("*");                    // left or right edge of this row
                } else {
                    System.out.print(" ");                    // interior of this row stays hollow
                }
            }
            System.out.println();                          // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hollowHourglass(4);
    }
